 */
scwin.realInvstgAttachForm_onsubmit = function(e){
    try {
        return false

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil22120.realInvstgAttachForm_onsubmit' }); }
};

/**
 * @method
 * @name realInvstgDataForm_onsubmit
