 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.realInvstgDataForm_onsubmit = function(e){
    try {
        return false

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil22120.realInvstgDataForm_onsubmit' }); }
};

/**
 * @method
 * @name ipt_realInvstgMajContnCd_onclick
 * @description ipt_realInvstgMajContnCd 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_realInvstgMajContnCd_onclick = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil22120.ipt_realInvstgMajContnCd_onclick' }); }
};

/**
 * @method
 * @name btn_FileDown_onclick
 * @description btn_FileDown 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_FileDown_onclick = async function(e){
    try {
        await scwin.fileDown('' + dlt_realInvstgDataDetailRealInvstgDataFileList.getCellData(0, "bzProcsNo") + '','' + dlt_realInvstgDataDetailRealInvstgDataFileList.getCellData(0, "attachFileSeq") + '','' + dlt_realInvstgDataDetailRealInvstgDataFileList.getCellData(0, "attachFileNm") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil22120.btn_FileDown_onclick' }); }
};

/**
 * @method
 * @name btn_list_onclick
 * @description 「목록」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_list_onclick = function(e){
    try {
        scwin.list()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil22120.btn_list_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_FileDown
 * @description File Down 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_FileDown = async function () {
    try { return await $c.data.downFile("/company/filedown.do", "", ($c.util.getComponent("dma_FileDownReq") ? $c.util.getComponent("dma_FileDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

/**
 * @method
 * @name list
 * @description list 처리
 * @returns {void}
 * @hidden N
 */
scwin.list = function () {
    $c.win.setPageFrameSrc($c.win.getFrame(), '/jldfil22100/jldfil22100.xml');
};

/**
 * @method
 * @name setLength
 * @description set Length 처리
 * @param {Object} obj 컴포넌트
 * @param {*} tdName tdName
 * @param {*} maxLength maxLength
 * @returns {void}
 * @hidden N
 */
scwin.setLength = function (obj, tdName, maxLength) {
    const strLength = scwin.calBytes(obj);
    ($c.util.getComponent(tdName) && $c.util.getComponent(tdName).setValue) ? $c.util.getComponent(tdName).setValue("(" + strLength + "/" + maxLength + ")") : (($c.util.getComponent(tdName) && $c.util.getComponent(tdName).setText) ? $c.util.getComponent(tdName).setText("(" + strLength + "/" + maxLength + ")") : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + tdName), void ("(" + strLength + "/" + maxLength + ")")));
};

/**
 * @method
 * @name estimateCounter
 * @description estimate Counter 처리
 * @param {Object} obj 컴포넌트
 * @param {*} maxLength maxLength
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.estimateCounter = async function (obj, maxLength) {
    if (scwin.calBytes(obj.value) > maxLength) {
        await $c.win.alert('한글 2000자 이하, 숫자/영문 4000자 이하까지만 입력이 가능합니다.');
        obj.select();
        return;
    }
};

/**
 * @method
 * @name fileDown
 * @description file Down 처리
 * @param {String} contnId contnId
 * @param {*} ipt_contnAttachSeq ipt_contnAttachSeq
 * @param {String} ipt_attachFileNm ipt_attachFileNm
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileDown = async function (contnId, ipt_contnAttachSeq, ipt_attachFileNm) {
    const frm = (document.RealInvstgDataForm || { elements: [] });
    $('#realInvstgAttachForm').attr("action", "realInvstgFiledown.do");
    $c.util.getComponent('ipt_method').setValue("realInvstgDataAttachFile");
    $('#realInvstgAttachForm').attr("onsubmit", "");
    $c.util.getComponent('ipt_bzProcsNo').setValue(contnId);
    $c.util.getComponent('ipt_contnAttachSeq').setValue(ipt_contnAttachSeq);
    $c.util.getComponent('ipt_attachFileNm').setValue(ipt_attachFileNm);
    await scwin.tx_fn_FileDown();
};

/**
 * @method
 * @name calBytes
 * @description cal Bytes 처리
 * @param {String} str str
 * @returns {void}
 * @hidden N
 */
scwin.calBytes = function (str) {
    let tcount = 0;
    const tmpStr = new String(str);
    const temp = tmpStr.length;
    let onechar;
    for (let k = 0; k < temp; k++) {
        onechar = tmpStr.charAt(k);
        if (escape(onechar).length > 4) {
            tcount += 2;
        } else {
            if (escape(onechar) === '%0A') {
                tcount += 2;
            } else {
                tcount += 1;
            }
        }
    }
    return tcount;
};
